export type ParamsFor<M extends Method> = MethodParams[M];
export type ResultFor<M extends Method> = MethodResults[M];
export type MethodsWithEmptyParams = "pm_system_version" | "pm_project_list" | "pm_agent_catalog_read" | "pm_settings_read";
export type CallArgs<M extends Method> = M extends MethodsWithEmptyParams
  ? [params?: ParamsFor<M>]
  : [params: ParamsFor<M>];
const PM_REQUEST_TIMEOUT_MS = 12_000;
const PM_LONG_RUNNING_REQUEST_TIMEOUT_MS = 300_000;
const PM_LONG_RUNNING_METHODS: readonly Method[] = ["pm_jira_pull","pm_jira_diff_read","pm_jira_apply","pm_jira_projects_read","pm_jira_statuses_read","pm_jira_favourite_filters_read","pm_jira_search","pm_agent_launch","pm_check_start","pm_skill_run","pm_skill_creator_launch","pm_skill_draft_dry_run"];
export function pmRequestTimeoutMs(method: Method): number {
  // Jira and agent launches wait on bounded provider and process work.
  return PM_LONG_RUNNING_METHODS.includes(method) ? PM_LONG_RUNNING_REQUEST_TIMEOUT_MS : PM_REQUEST_TIMEOUT_MS;
}
function isJsonObject(value: unknown): value is Record<string, unknown> {
  return typeof value === "object" && value !== null && !Array.isArray(value);
}

function jsonArrayUnique(values: unknown[]): boolean {
  return values.every((value, index) =>
    !values.slice(index + 1).some((candidate) => JSON.stringify(candidate) === JSON.stringify(value))
  );
}

